  let destinoSelecionado=null,timer=null;
  const ajustar=()=>{const rem=m.querySelector('#eca-status').value==='REMANEJADO';m.querySelector('#eca-local-wrap').style.display=rem?'none':'';m.querySelector('#eca-remanejado-wrap').style.display=rem?'block':'none';m.querySelector('#eca-ajuda').textContent=rem?'REMANEJADO exige vínculo com uma Unidade de Ensino cadastrada. O local atual será derivado do vínculo e a movimentação ficará registrada na cadeia de custódia.':'Situação funcional, status e localização permanecem independentes para os demais estados do acervo.';};
  m.querySelector('#eca-status').addEventListener('change',ajustar);ajustar();
