async function carregarDescredenciamento(){const host=$('#extd-descredenciamento-lista');if(!host)return;host.innerHTML='<div class="extd-panel">Carregando processos de descredenciamento…</div>';try{const xs=await S().listarDescredenciamento(),ct=$('#extd-count-descredenciamento');if(ct)ct.textContent=String(xs.length);host.innerHTML=xs.length?`<div class="extd-grid">${xs.map(x=>`<article class="extd-card"><span class="extd-badge">${esc(String(x.tipo||'PROCESSO').replaceAll('_',' '))}</span><h3>${esc(x.escola_nome)}</h3><p>${esc(x.municipio||'')} · NTE ${esc(x.nte_id||'—')}</p><small>${x.numero_sei?'SEI '+esc(x.numero_sei)+' · ':''}${esc(String(x.etapa_atual||'').replaceAll('_',' '))}</small><div class="extd-actions"><button class="extd-btn primary" data-open-desc="${x.id}">Abrir processo</button></div></article>`).join('')}</div>`:'<div class="extd-panel">Nenhuma escola em processo de descredenciamento.</div>';host.querySelectorAll('[data-open-desc]').forEach(b=>b.onclick=()=>abrir(Number(b.dataset.openDesc)));}catch(e){host.innerHTML=`<div class="extd-panel">Falha ao carregar processos: ${esc(e.message||e)}</div>`}}
